#!/usr/bin/env python3
"""Patches the Android project generated by `flutter create` for PixeilShop."""
import pathlib
import re
import shutil

manifest = pathlib.Path('android/app/src/main/AndroidManifest.xml')
s = manifest.read_text(encoding='utf-8')

perms = (
    '    <uses-permission android:name="android.permission.INTERNET"/>\n'
    '    <uses-permission android:name="android.permission.RECORD_AUDIO"/>\n'
    '    <uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" android:maxSdkVersion="28"/>\n'
)
if 'RECORD_AUDIO' not in s:
    s = s.replace('<application', perms + '    <application', 1)

speech_intent = '<intent><action android:name="android.speech.RecognitionService"/></intent>'
if 'RecognitionService' not in s:
    if '<queries>' in s:
        s = s.replace('<queries>', '<queries>\n        ' + speech_intent, 1)
    else:
        s = s.replace('</manifest>', '    <queries>\n        ' + speech_intent + '\n    </queries>\n</manifest>', 1)

meta = '\n        <meta-data android:name="com.google.mlkit.vision.DEPENDENCIES" android:value="subject_segment"/>'
if 'mlkit.vision.DEPENDENCIES' not in s:
    s = re.sub(r'(<application[^>]*>)', lambda m: m.group(1) + meta, s, count=1)

s = re.sub(r'android:label="[^"]*"', 'android:label="PixeilShop"', s, count=1)
manifest.write_text(s, encoding='utf-8')

for name in ('build.gradle.kts', 'build.gradle'):
    f = pathlib.Path('android/app') / name
    if f.exists():
        t = f.read_text(encoding='utf-8')
        t = t.replace('flutter.minSdkVersion', '24')
        f.write_text(t, encoding='utf-8')
        print('patched', f)
print('manifest patched')

# بعض الإضافات (مثل tflite_flutter) تُترجَم بـ Java 1.8 و Kotlin 17 فيفشل فحص التوافق.
# نحوّل الفحص إلى تحذير بدل خطأ.
gp = pathlib.Path('android/gradle.properties')
txt = gp.read_text(encoding='utf-8') if gp.exists() else ''
if 'kotlin.jvm.target.validation.mode' not in txt:
    if txt and not txt.endswith('\n'):
        txt += '\n'
    txt += 'kotlin.jvm.target.validation.mode=warning\n'
    gp.write_text(txt, encoding='utf-8')
print('gradle.properties patched')

# أيقونة التطبيق: ننسخ مجلدات mipmap الجاهزة (عادية + Adaptive) فوق الأيقونة الافتراضية.
src = pathlib.Path(__file__).parent / 'android_res'
dst = pathlib.Path('android/app/src/main/res')
if src.exists():
    shutil.copytree(src, dst, dirs_exist_ok=True)
    print('launcher icons copied')
